/* Movimento original congelado antes do P1C.3B.2: não modificar. */
function doMove(dx,dy){if(!G||G.over)return;const p=G.hero,x=p.x+dx,y=p.y+dy;if(!walk(x,y)){beep(120,.035);return;}const e=enemyAt(x,y);if(e){attack(e,true);return;}p.x=x;p.y=y;G.steps++;beep(190,.028);const roomIndex=G.rooms.findIndex(room=>x>=room.x&&x<room.x+room.w&&y>=room.y&&y<room.y+room.h);if(roomIndex>=0&&!G.visitedRooms.includes(roomIndex)){G.visitedRooms.push(roomIndex);relicEvent('onEnterRoom',{roomIndex});}const item=G.items.find(i=>i.x===x&&i.y===y);if(item){G.items=G.items.filter(i=>i!==item);collect(item);}if(G.over)return;const inShrine=G.shrine&&G.shrine.x===x&&G.shrine.y===y&&!G.altarUsed;let onStairs=G.stairs.x===x&&G.stairs.y===y;reveal();worldTurn();if(G.over)return;if(G.pendingRelicOffer){if($('overlay').classList.contains('hidden'))showPendingRelicOffer();}else if(inShrine){G.altarUsed=true;shrineModal();}else if(onStairs){stairsModal();}updateHUD();save();}
